class Lesson {
  final int id;
  final String category;
  final String title;
  final String rule;
  final String example;
  const Lesson(this.id, this.category, this.title, this.rule, this.example);
}

const List<Lesson> academyLessons = [
  // БЛОК 1: БАЗА И БЕЗОПАСНОСТЬ (1-15)
  Lesson(1, 'База', '001. Подушка безопасности', 'Не инвестируй последние деньги. Сначала отложи 3–6 месячных расходов на накопительный счёт.', 'Тратишь 50 тыс./мес. -> 150–300 тыс. держишь на вкладе с быстрым снятием.'),
  Lesson(2, 'База', '002. Инфляция и реальная доходность', 'Реальная доходность = Доходность инвестиций минус Инфляция.', 'Вклад даёт 16%, инфляция 9%. Твой реальный плюс — около 7% покупательной способности.'),
  Lesson(3, 'База', '003. Сложный процент', 'Проценты начисляются на проценты, если ты не выводишь купоны и дивиденды, а покупаешь на них новые бумаги.', '100 000 ₽ под 15% годовых за 10 лет превращаются в 404 556 ₽ без доп. вложений.'),
  Lesson(4, 'База', '004. Брокерский счёт vs ИИС-3', 'Обычный счёт позволяет выводить деньги в любой момент. ИИС-3 даёт налоговые льготы при сроке от 5 лет.', 'Новичкам выгодно иметь оба: ИИС для долгосрока, обычный — для гибкости.'),
  Lesson(5, 'База', '005. Лицензия ЦБ РФ', 'Работай только через брокеров с официальной лицензией Банка России.', 'Сбер, Т-Инвестиции, ВТБ, БКС, Финам имеют лицензию. Телеграм-боты — это мошенники.'),
  Lesson(6, 'База', '006. Биржевой стакан', 'Таблица заявок на покупку (зелёные — Bid) и продажу (красные — Ask) в реальном времени.', 'Покупатели хотят купить дешевле (по 100 ₽), продавцы продать дороже (по 101 ₽).'),
  Lesson(7, 'База', '007. Лимитная и рыночная заявка', 'Рыночная покупает мгновенно по текущей цене. Лимитная ждёт указанную тобой цену.', 'На неликвидных бумагах ставь только лимитную заявку, чтобы не купить втридорога.'),
  Lesson(8, 'База', '008. Спред (разница цен)', 'Разница между лучшей ценой покупки и продажи в стакане. Чем меньше спред, тем ликвиднее бумага.', 'В акциях Сбера спред 1 копейка, а в редкой облигации может быть 20 рублей.'),
  Lesson(9, 'База', '009. Ликвидность актива', 'Способность быстро продать актив по рыночной цене без потери стоимости.', 'Фонды ликвидности (LQDT) и голубые фишки можно продать за секунду на миллионы рублей.'),
  Lesson(10, 'База', '010. Режим торгов Т+1', 'При покупке или продаже ценных бумаг на Мосбирже расчёты официально фиксируются на следующий рабочий день.', 'Продал акции в пятницу — вывести деньги без комиссии за плечо лучше в понедельник.'),
  Lesson(11, 'База', '011. Маржинальная торговля (Плечи)', 'Торговля в долг у брокера. Увеличивает не только потенциальную прибыль, но и убытки, плюс капает ежедневная комиссия.', 'Новичкам категорически отключить в настройках брокера!'),
  Lesson(12, 'База', '012. Шорт (Короткая позиция)', 'Берёшь акции у брокера в долг, продаёшь дорого, ждёшь падения, откупаешь дешевле и возвращаешь долг.', 'Опасно тем, что падение ограничено 100%, а рост цены (и твой убыток) не ограничен ничем.'),
  Lesson(13, 'База', '013. Диверсификация', 'Распределение капитала между разными классами активов, отраслями и валютами.', 'Не бери только нефтяников: добавь банки, IT, ОФЗ, золото и фонды денежного рынка.'),
  Lesson(14, 'База', '014. Риск-профиль инвестора', 'Твоя готовность спокойно смотреть на временную просадку портфеля без панических продаж.', 'Консерватор держит 80% в облигациях, агрессивный инвестор — до 80% в акциях.'),
  Lesson(15, 'База', '015. Горизонт инвестирования', 'Срок, на который ты вкладываешь деньги без необходимости их вынимать.', 'Деньги нужны через полгода на отпуск? Только вклад или LQDT, никаких акций!'),

  // БЛОК 2: ОБЛИГАЦИИ И ФОНДЫ (16-35)
  Lesson(16, 'Облигации', '016. Что такое облигация', 'Долговая расписка государства (ОФЗ) или компании. Ты даёшь в долг под фиксированный или плавающий процент.', 'В дату погашения эмитент обязан вернуть ровно 100% номинала (обычно 1000 ₽).'),
  Lesson(17, 'Облигации', '017. Номинал и рыночная цена', 'Цена облигации на бирже указывается в процентах от её номинала.', 'Цена 85.4% при номинале 1000 ₽ означает, что бумага стоит 854 ₽.'),
  Lesson(18, 'Облигации', '018. Купон облигации', 'Регулярный процентный платёж по облигации (раз в месяц, квартал или полгода).', 'Купон 15% от 1000 ₽ даёт 150 ₽ в год до вычета налога 13%.'),
  Lesson(19, 'Облигации', '019. Что такое НКД', 'Накопленный купонный доход. Покупатель платит продавцу часть купона за дни, пока тот владел бумагой.', 'Продал облигацию за день до выплаты купона — не потерял проценты, их вернул покупатель через НКД.'),
  Lesson(20, 'Облигации', '020. Доходность к погашению (YTM)', 'Полная расчётная доходность облигации с учётом всех купонов и разницы между ценой покупки и номиналом.', 'Купил ОФЗ за 700 ₽, погасят за 1000 ₽ + купоны = итоговая YTM выше купонной ставки.'),
  Lesson(21, 'Облигации', '021. ОФЗ-ПД (Постоянный доход)', 'Государственные облигации с фиксированным купоном на весь срок жизни бумаги.', 'Идеальны, когда ждёшь снижения ключевой ставки ЦБ: их цена на бирже тогда сильно растёт.'),
  Lesson(22, 'Облигации', '022. ОФЗ-ФК (Флоатеры)', 'Облигации с плавающим купоном, привязанным к ставке RUONIA или ключевой ставке ЦБ.', 'Защищают портфель при росте ставок: ставка ЦБ выше -> твой купон автоматически выше.'),
  Lesson(23, 'Облигации', '023. ОФЗ-ИН (Инфляционные)', 'Номинал такой облигации ежедневно индексируется на величину официальной инфляции (ИПЦ).', 'Защита от скачков цен на длинном горизонте.'),
  Lesson(24, 'Облигации', '024. Корпоративные облигации', 'Долговые бумаги частных и госкомпаний (РЖД, МТС, Газпром). Платят больше ОФЗ за счёт риска компании.', 'Всегда проверяй кредитный рейтинг компании перед покупкой (ищем от A- до AAA).'),
  Lesson(25, 'Облигации', '025. ВДО (Высокодоходные облигации)', 'Облигации небольших компаний с высоким купоном, но повышенным риском дефолта (рейтинг BBB и ниже).', 'Не выделяй на ВДО больше 5–10% портфеля и бери минимум 10 разных эмитентов.'),
  Lesson(26, 'Облигации', '026. Дюрация облигации', 'Показывает чувствительность цены облигации к изменению ключевой ставки ЦБ.', 'Если дюрация 4 года, то при росте ставки ЦБ на 1% цена бумаги упадёт примерно на 4%.'),
  Lesson(27, 'Облигации', '027. Оферта (Put и Call)', 'Дата, когда инвестор может предъявить бумагу к досрочному выкупу по номиналу, а эмитент — изменить купон.', 'Опасность Put-оферты: если пропустить подачу заявления брокеру, купон могут снизить до 0.01%!'),
  Lesson(28, 'Облигации', '028. Амортизация долга', 'Возврат номинала облигации не в самом конце срока, а частями вместе с купонами.', 'Удобно для снижения риска: тело долга возвращается постепенно, можно перекладывать в новые бумаги.'),
  Lesson(29, 'Облигации', '029. Дефолт и техдефолт', 'Неспособность компании выплатить купон или погасить номинал вовремя.', 'В ОФЗ дефолт практически невозможен (печатают рубли), в мелких ВДО случается регулярно.'),
  Lesson(30, 'Облигации', '030. Кредитные рейтинги (АКРА / Эксперт РА)', 'Оценка надёжности компании от российских рейтинговых агентств по шкале от D до AAA.', 'Новичку стоит выбирать бумаги с рейтингом не ниже A- (высокая надёжность).'),
  Lesson(31, 'Фонды', '031. Что такое БПИФ (Паи)', 'Биржевой паевой инвестиционный фонд — готовая корзина активов в одной бумаге.', 'Покупая 1 пай за 100 ₽, ты сразу покупаешь доли в 40 крупнейших компаниях РФ.'),
  Lesson(32, 'Фонды', '032. Фонды денежного рынка (LQDT, SBMM, TMON)', 'Копилка внутри брокерского счёта: дают доходность около ключевой ставки ЦБ каждый день без просадок.', 'Идеальная замена накопительному счёту для хранения кэша перед покупками на просадках.'),
  Lesson(33, 'Фонды', '033. Комиссия за управление БПИФ (TER)', 'Ежегодная плата управляющей компании, которая незаметно удерживается из стоимости пая.', 'Выбирай индексные фонды с комиссией до 0.8–1% годовых, иначе на дистанции потеряешь много прибыли.'),
  Lesson(34, 'Фонды', '034. Налоговая льгота БПИФ', 'Внутри российского БПИФа приходят дивиденды и купоны, но фонд не платит с них 13% налог при реинвестировании.', 'Это ускоряет сложный процент по сравнению с самостоятельной покупкой тех же бумаг.'),
  Lesson(35, 'Фонды', '035. Золото на бирже (GLDRUB_TOM и фонды)', 'Инструмент защиты от девальвации рубля и мировых кризисов.', 'На Мосбирже выгоднее покупать биржевое золото GLDRUB_TOM или фонды на физическое золото в хранилище.'),

  // БЛОК 3: АКЦИИ И 4 ФИЛЬТРА ПРОФИ (36-60)
  Lesson(36, 'Акции', '036. Что такое акция', 'Доля в реальном бизнесе. Покупая акцию, ты становишься совладельцем компании.', 'Рост бизнеса и его прибыли со временем толкает вверх цену акций и размер дивидендов.'),
  Lesson(37, 'Акции', '037. Обыкновенные и привилегированные (префы)', 'Обычка даёт право голоса на собрании. Префы (Сбер-п, Сургут-п) обычно гарантируют дивиденды по уставу.', 'Для частного инвестора префы часто выгоднее из-за более высокой дивидендной доходности.'),
  Lesson(38, 'Акции', '038. Голубые фишки (Первый эшелон)', 'Самые крупные, надёжные и ликвидные компании страны (Сбер, Лукойл, Газпром, Роснефть, Яндекс).', 'Фундамент любого портфеля акций: низкие спреды и понятная отчётность.'),
  Lesson(39, 'Акции', '039. Второй и третий эшелон', 'Средние и малые компании с низкой ликвидностью. Могут вырасти в разы, но и упасть на 50% за день.', 'Никогда не покупай третий эшелон по сигналам из телеграм-каналов (это схема Pump & Dump).'),
  Lesson(40, 'Акции', '040. Дивидендная отсечка и гэп', 'Последний день покупки акции для получения дивидендов. На следующее утро цена падает примерно на размер выплаты.', 'Не пугайся падения в день отсечки: ты получишь эти деньги на счёт через 2–3 недели.'),
  Lesson(41, 'Акции', '041. Дивидендная политика', 'Официальный документ компании, где написано, какую долю прибыли она обещает платить акционерам.', 'Например: Сбер платит 50% чистой прибыли по МСФО, а Лукойл — до 100% свободного денежного потока.'),
  Lesson(42, 'Акции', '042. Акции роста vs Акции стоимости', 'Компании роста (Яндекс, Ozon, Астра) вкладывают всю прибыль в захват рынка. Компании стоимости (МТС, Лукойл) платят щедрые дивиденды.', 'Хороший портфель сочетает и дойных коров, и растущих лидеров.'),
  Lesson(43, 'Акции', '043. Выкуп акций (Buyback)', 'Компания выкупает собственные акции с биржи и часто гасит их. Доля каждого оставшегося акционера растёт.', 'Байбэк поддерживает котировки и увеличивает будущие дивиденды на одну акцию.'),
  Lesson(44, 'Акции', '044. Допэмиссия (Размытие доли)', 'Выпуск компанией новых акций. Если твоя доля не увеличивается, твой кусок пирога в бизнесе сжимается.', 'Частая допэмиссия у закредитованных компаний (например, ВК или Сегежа) — сильный негатив для котировок.'),
  Lesson(45, 'Акции', '045. Отчётность МСФО и РСБУ', 'РСБУ — бухгалтерский отчёт только головной компании для налоговой. МСФО — полный отчёт всего холдинга с дочками.', 'Всегда принимай инвестиционные решения на основе отчёта МСФО!'),
  Lesson(46, '4 Фильтра', '046. Фильтр 1: P/E (Окупаемость)', 'Капитализация компании делённая на годовую чистую прибыль. Показывает, за сколько лет бизнес окупит себя.', 'Для рынка РФ норма P/E от 4 до 7. Если P/E > 15 без бурного роста выручки — бумага переоценена.'),
  Lesson(47, '4 Фильтра', '047. Фильтр 2: Долг (Net Debt / EBITDA)', 'Показывает, за сколько лет компания может погасить все кредиты из своей операционной прибыли.', 'Безопасно: меньше 1.5x. Опасно при высоких ставках ЦБ: выше 2.5x–3.0x!'),
  Lesson(48, '4 Фильтра', '048. Фильтр 3: Рентабельность (ROE)', 'Эффективность использования капитала акционеров. Сколько копеек прибыли приносит каждый вложенный рубль.', 'Ищем лидеров отрасли с ROE выше 20% (например, у Сбера ROE стабильно около 22–25%).'),
  Lesson(49, '4 Фильтра', '049. Фильтр 4: Свободный денежный поток (FCF)', 'Реальные живые деньги, которые остаются на счетах после всех расходов и стройки заводов (CAPEX).', 'Именно из положительного FCF платятся здоровые дивиденды без влезания в кредиты.'),
  Lesson(50, '4 Фильтра', '050. Мультипликатор P/BV (Для банков)', 'Отношение цены банка к его собственному капиталу (балансовой стоимости).', 'Покупать сильный банк по P/BV около 0.7–1.0 — отличная сделка. Выше 1.5 — уже дорого.'),
  Lesson(51, '4 Фильтра', '051. Мультипликатор EV/EBITDA', 'Сравнивает реальную стоимость бизнеса (с учётом его долгов) с операционной прибылью до налогов.', 'Позволяет честно сравнить закредитованную компанию и компанию с кубышкой кэша. Норма в РФ: 3–5x.'),
  Lesson(52, 'Акции', '052. Кубышка (Отрицательный чистый долг)', 'Ситуация, когда денег на вкладах у компании больше, чем всех её кредитов.', 'Пример: Сургутнефтегаз, Лукойл, Интер РАО. В эпоху высоких ставок они зарабатывают миллиарды просто на процентах!'),
  Lesson(53, 'Акции', '053. Циклические компании', 'Металлурги, угольщики, застройщики и удобрения: их прибыль сильно зависит от мировых цен на сырьё и ставок.', 'Парадокс: циклические акции нужно покупать, когда у них плохие отчёты и высокий P/E (дно цикла), а продавать на пике прибыли.'),
  Lesson(54, 'Акции', '054. Защитные сектора', 'Продуктовый ритейл (X5, Магнит) и электроэнергетика: люди покупают еду и жгут свет в любой кризис.', 'Такие компании перекладывают инфляцию в ценники на полках магазинов.'),
  Lesson(55, 'Акции', '055. Экспортёры vs Внутренний рынок', 'Нефтяники и металлурги выигрывают от слабого рубля. Банки, IT и ритейл работают внутри страны за рубли.', 'Держи в портфеле обе группы, чтобы не гадать, куда пойдёт курс доллара и юаня.'),
  Lesson(56, 'Акции', '056. Сплит акций (Дробление)', 'Уменьшение цены одной акции в несколько раз с пропорциональным увеличением их количества у инвесторов.', 'Транснефть раздробила акцию за 150 000 ₽ в 100 раз -> бумага стала стоить 1 500 ₽ и стала доступна всем.'),
  Lesson(57, 'Акции', '057. IPO (Первичное размещение)', 'Первый выход частной компании на биржу. Часто сопровождается агрессивной рекламой и завышенной ценой.', 'Правило профи: пропусти ажиотаж на IPO и посмотри на компанию через полгода после первых отчётов.'),
  Lesson(58, 'Акции', '058. Делистинг', 'Уход акций компании с биржи по решению владельцев или из-за банкротства.', 'Не держи бумаги компаний на грани банкротства — после делистинга продать их почти невозможно.'),
  Lesson(59, 'Акции', '059. Индекс Мосбиржи (IMOEX)', 'Главный индикатор из ~45 крупнейших акций РФ. Показывает среднюю температуру по фондовому рынку.', 'Индекс полной доходности (MCFTR) учитывает ещё и реинвестированные дивиденды — именно с ним сравнивай свой портфель.'),
  Lesson(60, 'Акции', '060. Календарь инвестора', 'Сезонность рынка: основные дивиденды в РФ платят в мае–июле (летний дивсезон) и зимой (промежуточные).', 'Покупать дивидендные фишки выгоднее за 3–4 месяца до отсечки, пока толпа ещё не разогнала цену.'),

  // БЛОК 4: ФЬЮЧЕРСЫ И ОПЦИОНЫ БЕЗ СЛИВА (61-75)
  Lesson(61, 'Срочный рынок', '061. Что такое фьючерс', 'Контракт на покупку или продажу актива в будущем по фиксированной сегодня цене.', 'Торгуется на срочной секции FORTS. Бывает поставочный (поставка акций) и расчётный (только деньги).'),
  Lesson(62, 'Срочный рынок', '062. Гарантийное обеспечение (ГО)', 'Залог, который брокер блокирует на счёте при открытии фьючерса (обычно 10–20% от стоимости контракта).', 'Внимание: вшитое плечо! Чтобы не слить счёт, держи на счету 100% полной стоимости контракта в фонде LQDT.'),
  Lesson(63, 'Срочный рынок', '063. Вариационная маржа и клиринг', 'Дважды в день (в 14:00 и 18:50 МСК) биржа проводит клиринг: списывает убыток или начисляет прибыль по фьючерсу живыми деньгами.', 'Если свободных рублей не хватит для списания вариационной маржи, брокер принудительно закроет позицию!'),
  Lesson(64, 'Срочный рынок', '064. Дата экспирации', 'День окончания жизни фьючерса или опциона, когда происходят финальные расчёты.', 'Долгосрочному инвестору нужно заранее перекладываться в следующий квартальный контракт (роллирование).'),
  Lesson(65, 'Срочный рынок', '065. Контанго и Бэквордация', 'Контанго — фьючерс дороже базового актива (норма за счёт ключевой ставки). Бэквордация — фьючерс дешевле из-за ожидания дивидендов.', 'Не шорти фьючерс перед дивидендами, надеясь на бесплатный профит от гэпа — дивиденд уже заложен в бэквордацию!'),
  Lesson(66, 'Срочный рынок', '066. Хеджирование портфеля', 'Страховка основного портфеля акций или валюты с помощью обратной позиции во фьючерсе.', 'Боишься обвала рынка перед геополитическим событием, но не хочешь продавать акции и терять ЛДВ? Открой шорт фьючерса на Индекс (MIX/MXI).'),
  Lesson(67, 'Срочный рынок', '067. Валютные фьючерсы (Si, CNY, Eu)', 'Расчётные контракты на курс доллара, юаня и евро без риска блокировки самой иностранной валюты.', 'Позволяют отыграть ослабление рубля с минимальной комиссией.'),
  Lesson(68, 'Срочный рынок', '068. Товарные фьючерсы (Золото, Нефть, Газ)', 'Контракты на мировые цены сырья (BR — нефть Brent, GD — золото, NG — природный газ).', 'Фьючерс на природный газ (NG) называют «вдоводелом» из-за бешеной волатильности — новичкам туда вход строго запрещён.'),
  Lesson(69, 'Срочный рынок', '069. Что такое опцион (Call и Put)', 'Опцион Call даёт ПРАВО купить актив по фиксированной цене (страйк), опцион Put — ПРАВО продать.', 'В отличие от фьючерса, у покупателя опциона риск строго ограничен уплаченной за него премией!'),
  Lesson(70, 'Срочный рынок', '070. Покупка vs Продажа опционов', 'Покупатель опциона рискует только стоимостью контракта (премией). Продавец опциона несёт неограниченный риск.', 'Золотое правило безопасности: никогда не продавай непокрытые («голые») опционы!'),
  Lesson(71, 'Срочный рынок', '071. Страйк и премия опциона', 'Страйк — цена актива, зашитая в условии опциона. Премия — цена самого опциона, которую ты платишь за страховку.', 'Купил Put-опцион на Сбер со страйком 250 ₽ за премию 5 ₽: если Сбер упадёт до 200 ₽, ты заработаешь 45 ₽ чистыми.'),
  Lesson(72, 'Срочный рынок', '072. Временной распад опциона (Тета)', 'Опцион теряет свою стоимость каждый день по мере приближения даты экспирации, если цена стоит на месте.', 'Как полис КАСКО: каждый прожитый без аварии день сжигает часть стоимости страховки.'),
  Lesson(73, 'Срочный рынок', '073. Покрытый Call (Инвестиционная стратегия)', 'У тебя есть 100 акций Сбера, и ты продаёшь на них опцион Call со страйком выше текущей цены, получая премию.', 'Если акция не вырастет — премия остаётся тебе как дополнительный дивиденд.'),
  Lesson(74, 'Срочный рынок', '074. Защитный Put (Страховка от краха)', 'Покупка опциона Put под имеющийся пакет акций перед важным отчётом или заседанием ЦБ.', 'Ограничивает максимальный убыток по портфелю на заданном уровне.'),
  Lesson(75, 'Срочный рынок', '075. Чек-лист безопасности на FORTS', '1. Никаких плечей свыше 1:1. 2. Запас кэша на вариационную маржу. 3. Только лимитные заявки в стакане.', 'Срочный рынок создан для страховки (хеджа), а не для игры в казино.'),

  // БЛОК 5: НОВОСТИ, НАЛОГИ И РЕБАЛАНСИРОВКА (76-100)
  Lesson(76, 'Новости и ЦБ', '076. Ключевая ставка ЦБ РФ', 'Главный рычаг экономики. Высокая ставка охлаждает инфляцию, но давит на акции и длинные облигации.', 'Ставка растёт -> покупаем флоатеры и фонды ликвидности. Ставка начинает цикл снижения -> перекладываемся в длинные ОФЗ-ПД и акции.'),
  Lesson(77, 'Новости и ЦБ', '077. Риторика пресс-релиза ЦБ', 'Рынок двигает не сам факт изменения ставки, а сигнал регулятора на будущее (жёсткий или мягкий).', 'Фраза «будет оценивать целесообразность дальнейшего повышения» — жёсткий сигнал, рынок падает.'),
  Lesson(78, 'Новости и ЦБ', '078. Данные Росстата по инфляции', 'Каждую среду в 19:00 МСК выходит недельная инфляция. Если она замедляется несколько недель подряд — рынок ждёт смягчения ЦБ.', 'Высокая недельная инфляция (>0.2%) перед заседанием ЦБ почти гарантирует жёсткое решение по ставке.'),
  Lesson(79, 'Новости и ЦБ', '079. Валютная переоценка и бюджетное правило', 'Ослабление рубля на 10% увеличивает рублёвую выручку экспортёров и будущие дивиденды нефтяников.', 'Но одновременно слабый рубль разгоняет инфляцию импорта, заставляя ЦБ держать ставку высокой.'),
  Lesson(80, 'Новости и ЦБ', '080. Правило 2 уровней новостей', 'Уровень 1 (шум): слухи, мнения блогеров, разовые штрафы. Уровень 2 (фундаментал): ставка ЦБ, налоги, отмена дивидендов, МСФО.', 'Никогда не меняй структуру портфеля на новостях 1-го уровня!'),
  Lesson(81, 'Новости и ЦБ', '081. Покупай на слухах, продавай на фактах', 'Крупные игроки закладывают ожидаемую новость в цену заранее. В день официального объявления часто идёт фиксация прибыли.', 'Акция росла месяц перед объявлением рекордных дивидендов, а в день выхода новости упала на 3% — это фиксация «на фактах».'),
  Lesson(82, 'Налоги', '082. НДФЛ с инвестиций', 'Базовая ставка налога на прибыль от сделок, купонов и дивидендов составляет 13% (и 15% с доходов свыше 2.4 млн ₽ в год).', 'Брокер сам является налоговым агентом: считает и удерживает налог автоматически при выводе денег или в конце года.'),
  Lesson(83, 'Налоги', '083. ЛДВ (Льгота долгосрочного владения)', 'Если продержать акции или БПИФы российских компаний непрерывно более 3 лет, прибыль от их роста освобождается от налога!', 'Лимит освобождения — до 3 млн рублей чистой прибыли за каждый год владения (за 3 года — 9 млн ₽ без налога).'),
  Lesson(84, 'Налоги', '084. ИИС-3: Двойная налоговая льгота', 'Объединяет возврат НДФЛ со взносов (до 400 тыс. ₽ в год) и освобождение инвестиционного дохода от налога при закрытии (до 30 млн ₽).', 'При официальной зарплате даёт гарантированные 13–15% от государства сверху к доходности бумаг.'),
  Lesson(85, 'Налоги', '085. Сальдирование убытков', 'Убыток от продажи одних акций уменьшает налогооблагаемую прибыль от продажи других акций в том же году.', 'В декабре выгодно продать убыточную бумагу и тут же откупить её обратно, чтобы вернуть излишне удержанный за год налог!'),
  Lesson(86, 'Налоги', '086. Особенность налогов с дивидендов', 'Налог с дивидендов удерживается сразу до зачисления на счёт и НЕ сальдируется с убытками от продажи акций.', 'Но купоны по облигациям входят в общую базу и отлично сальдируются с убытками по облигациям и акциям.'),
  Lesson(87, 'Портфель', '087. Аллокация активов (Структура портфеля)', '90% успеха портфеля зависит от правильных долей классов активов (акции / облигации / кэш / золото), а не от угадывания одной ракеты.', 'Классический сбалансированный портфель: 40% акции, 40% облигации (ОФЗ + флоатеры), 10% фонд ликвидности, 10% золото.'),
  Lesson(88, 'Портфель', '088. Что такое ребалансировка', 'Возврат долей активов к исходному плану раз в полгода или при отклонении доли более чем на 5%.', 'Акции выросли и стали занимать 60% вместо 40%? Направляй новые пополнения и купоны только в облигации.'),
  Lesson(89, 'Портфель', '089. Безналоговая ребалансировка', 'Выравнивание долей портфеля не через продажу выросших бумаг (чтобы не платить 13% налог и не терять ЛДВ), а за счёт свежих пополнений и купонов.', 'Самый математически выгодный способ управления капиталом для частного инвестора.'),
  Lesson(90, 'Портфель', '090. Метод DCA (Усреднение по времени)', 'Регулярная покупка активов равными суммами (например, с каждой зарплаты) независимо от новостей и индекса.', 'Избавляет от эмоций: когда рынок дорогой — покупаешь меньше штук, когда дешёвый — автоматически берёшь больше бумаг.'),
  Lesson(91, 'Портфель', '091. Лесенка облигаций', 'Распределение капитала между облигациями с погашением через 1, 2, 3, 4 и 5 лет.', 'Каждый год одна ступенька гасится по номиналу, давая живые деньги для реинвестирования по актуальным ставкам.'),
  Lesson(92, 'Портфель', '092. Штанга Талеба в инвестициях', 'Сочетание сверхнадёжных инструментов (80–90% в фондах ликвидности и ОФЗ) с небольшой долей сильных растущих идей (10–20%).', 'Ты полностью защищён от краха, но участвуешь в сильном росте рынка.'),
  Lesson(93, 'Психология', '093. Ловушка FOMO (Синдром упущенной выгоды)', 'Паническое желание купить акцию, которая уже выросла на 100%, потому что «все вокруг богатеют».', 'Покупка на эйфории толпы почти всегда заканчивается многолетней просадкой. Жди отката или ищи недооценённые идеи.'),
  Lesson(94, 'Психология', '094. Ошибка невозвратных затрат (Усреднение мусора)', 'Попытка докупать падающую компанию с плохим бизнесом и огромными долгами только ради снижения средней цены в терминале.', 'Усреднять можно только прибыльных лидеров рынка (по 4 фильтрам профи), упавших вместе со всем индексом!'),
  Lesson(95, 'Психология', '095. Эффект якоря', 'Привязка к историческому максимуму цены: «ВТБ стоил 10 копеек, а сейчас 2 — значит дешёвый!»', 'Цена в прошлом не имеет значения, если компания провела допэмиссии и размыла капитал. Смотри только на текущие мультипликаторы.'),
  Lesson(96, 'Практика', '096. Как читать скриншот портфеля', 'Первым делом оцени перекос по одной бумаге (не более 10–15% на эмитента) и по одному сектору (не более 25–30%).', 'Если 70% портфеля лежит в двух нефтяниках — это не портфель, а ставка на цены на нефть.'),
  Lesson(97, 'Практика', '097. Стресс-тест портфеля перед покупкой', 'Мысленно проверь, что будет с твоим счётом при: 1) Ставке ЦБ +3%, 2) Падении индекса на -25%, 3) Девальвации рубля на 20%.', 'Флоатеры спасут от ставки, кэш (LQDT) даст откупить дно акций, а экспортёры и золото защитят от девальвации.'),
  Lesson(98, 'Практика', '098. Чек-лист перед нажатием кнопки «Купить»', '1. Прошла ли бумага 4 фильтра? 2. Какая доля будет в портфеле? 3. Почему я покупаю и при каком условии продам?', 'Записанный до сделки план выключает панику во время рыночного шторма.'),
  Lesson(99, 'Практика', '099. Золотые правила защиты от мошенников', 'Никто на рынке не может гарантировать фиксированную доходность выше ключевой ставки ЦБ (кроме банковских вкладов и ОФЗ).', 'Обещают 5% в неделю, «инсайды», крипто-арбитраж или просят перевести на карту физлица? Это 100% обман.'),
  Lesson(100, 'Практика', '100. Путь от нуля до финансовой свободы', 'Капитал строят три кита: регулярная норма сбережений, дисциплина ребалансировки и время работы сложного процента.', 'Даже 10–15 тысяч рублей в месяц, системно инвестируемые по правилам без плечей и паники, создают мощный пассивный доход.'),
];

